+++ b/src/pages/content/folder/__tests__/folderDragDrop.test.ts
@@ -0,0 +1,213 @@
+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+
+import { FolderManager } from '../manager';
+import type { Folder, FolderData } from '../types';
+
+vi.mock('@/utils/i18n', () => ({
+  getTranslationSync: (key: string) => key,
+  getTranslationSyncUnsafe: (key: string) => key,
+  initI18n: () => Promise.resolve(),
+}));
+
+type TestableManager = {
+  data: FolderData;
+  containerElement: HTMLElement | null;
+  createFolderElement: (folder: Folder, level?: number) => HTMLElement;
+  clearAllDragStyles: () => void;
+  reorderOrMoveConversations: (
+    conversationIds: string[],
+    sourceParentId: string,
+    targetParentId: string,
+    insertIndex: number,
+    dragData?: unknown,
+  ) => void;
+};
+
+function createFolder(id = 'folder-1', name = 'Folder 1'): Folder {
+  const now = Date.now();
+  return {
+    id,
+    name,
+    parentId: null,
+    isExpanded: true,
+    createdAt: now,
+    updatedAt: now,
+  };
+}
+
+describe('folder drag and drop behavior', () => {
+  let manager: FolderManager | null = null;
+
+  beforeEach(() => {
+    vi.useFakeTimers();
+  });
+
+  afterEach(() => {
+    manager?.destroy();
+    manager = null;
+    document.body.innerHTML = '';
+    vi.runOnlyPendingTimers();
+    vi.useRealTimers();
+  });
+
+  it('adds native conversation when dropped onto a conversation inside a folder', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    typedManager.data = {
+      folders: [createFolder('folder-1')],
+      folderContents: {
+        'folder-1': [
+          {
+            conversationId: 'c_existing1',
+            title: 'Existing Chat',
+            url: 'https://gemini.google.com/app/existing1',
+            addedAt: Date.now(),
+          },
+        ],
+      },
+    };
+
+    const dragData = {
+      type: 'conversation',
+      conversationId: 'c_native123',
+      title: 'Native New Chat',
+      url: 'https://gemini.google.com/app/native123',
+    };
+
+    typedManager.reorderOrMoveConversations(
+      ['c_native123'],
+      'folder-1', // sourceParentId was undefined -> defaulted to folderId
+      'folder-1',
+      1,
+      dragData,
+    );
+
+    const folderConvs = typedManager.data.folderContents['folder-1'];
+    expect(folderConvs).toHaveLength(2);
+    expect(folderConvs.some((c) => c.conversationId === 'c_native123')).toBe(true);
+    expect(folderConvs.find((c) => c.conversationId === 'c_native123')?.title).toBe(
+      'Native New Chat',
+    );
+  });
+
+  it('inserts unstarred conversation at correct group position even when starred conversations exist', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    typedManager.data = {
+      folders: [createFolder('folder-1')],
+      folderContents: {
+        'folder-1': [
+          {
+            conversationId: 'c_star1',
+            title: 'Starred 1',
+            url: 'https://gemini.google.com/app/s1',
+            addedAt: 100,
+            starred: true,
+            sortIndex: 0,
+          },
+          {
+            conversationId: 'c_unstar1',
+            title: 'Unstarred 1',
+            url: 'https://gemini.google.com/app/u1',
+            addedAt: 200,
+            sortIndex: 0,
+          },
+          {
+            conversationId: 'c_unstar2',
+            title: 'Unstarred 2',
+            url: 'https://gemini.google.com/app/u2',
+            addedAt: 300,
+            sortIndex: 1,
+          },
+        ],
+      },
+    };
+
+    const dragData = {
+      type: 'conversation',
+      conversationId: 'c_new1',
+      title: 'New Unstarred',
+      url: 'https://gemini.google.com/app/new1',
+    };
+
+    // Dropping above Unstarred 1 (which is index 0 in unstarred group)
+    typedManager.reorderOrMoveConversations(
+      ['c_new1'],
+      'folder-1',
+      'folder-1',
+      0, // groupIndex = 0 for unstarred group
+      dragData,
+    );
+
+    const folderConvs = typedManager.data.folderContents['folder-1'];
+    const unstarredConvs = folderConvs.filter((c) => !c.starred);
+    expect(unstarredConvs[0].conversationId).toBe('c_new1');
+    expect(unstarredConvs[1].conversationId).toBe('c_unstar1');
+    expect(unstarredConvs[2].conversationId).toBe('c_unstar2');
+  });
+
+  it('clears all dragover styling classes via clearAllDragStyles', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    const container = document.createElement('div');
+    container.className = 'gv-folder-container';
+
+    const item1 = document.createElement('div');
+    item1.className = 'gv-folder-dragover';
+
+    const item2 = document.createElement('div');
+    item2.className = 'gv-folder-list-dragover';
+
+    const item3 = document.createElement('div');
+    item3.className = 'gv-reorder-above';
+
+    const item4 = document.createElement('div');
+    item4.className = 'gv-reorder-gap-active';
+
+    container.appendChild(item1);
+    container.appendChild(item2);
+    container.appendChild(item3);
+    container.appendChild(item4);
+    document.body.appendChild(container);
+
+    typedManager.containerElement = container;
+
+    typedManager.clearAllDragStyles();
+
+    expect(container.querySelectorAll('.gv-folder-dragover')).toHaveLength(0);
+    expect(container.querySelectorAll('.gv-folder-list-dragover')).toHaveLength(0);
+    expect(container.querySelectorAll('.gv-reorder-above')).toHaveLength(0);
+    expect(container.querySelectorAll('.gv-reorder-gap-active')).toHaveLength(0);
+  });
+
+  it('clears dragover styles on global drop event', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    const container = document.createElement('div');
+    container.className = 'gv-folder-container';
+    const listEl = document.createElement('div');
+    listEl.className = 'gv-folder-list gv-folder-list-dragover';
+    container.appendChild(listEl);
+    document.body.appendChild(container);
+
+    typedManager.containerElement = container;
+
+    // Attach global drop listener as done in initializeFolderUI
+    const globalDragCleanup = () => {
+      typedManager.clearAllDragStyles();
+    };
+    document.addEventListener('drop', globalDragCleanup);
+
+    expect(listEl.classList.contains('gv-folder-list-dragover')).toBe(true);
+
+    document.dispatchEvent(new Event('drop', { bubbles: true }));
+
+    expect(listEl.classList.contains('gv-folder-list-dragover')).toBe(false);
+
+    document.removeEventListener('drop', globalDragCleanup);
+  });
+});
