+        parentId: null,
+        isExpanded: true,
+        createdAt: Date.now(),
+        updatedAt: Date.now(),
+      },
+    ];
+    typed.data.folderContents['folder-1'] = [
+      {
+        conversationId: 'c_existing_1',
+        title: 'Existing Chat',
+        url: 'https://gemini.google.com/app/1',
+        addedAt: Date.now(),
+      },
+    ];
+
+    const convEl = document.createElement('div');
+    typed.setupConversationReorderZone(convEl, 'folder-1', 0);
+
+    const dragDataPayload = JSON.stringify({
+      type: 'conversation',
+      conversationId: 'c_external_1',
+      title: 'External Chat',
+      url: 'https://gemini.google.com/app/ext1',
+    });
+
