+  });
+
+  it('inserts an unstarred conversation at the exact index among unstarred siblings when starred items exist', () => {
+    manager = new FolderManager();
+    const typed = manager as unknown as TestableFolderManager;
+
+    typed.data.folders = [
+      {
+        id: 'folder-1',
+        name: 'Mixed Folder',
+        parentId: null,
+        isExpanded: true,
+        createdAt: Date.now(),
+        updatedAt: Date.now(),
+      },
+    ];
+    typed.data.folderContents['folder-1'] = [
+      {
+        conversationId: 'c_star_1',
+        title: 'Star 1',
+        starred: true,
+        url: 'https://gemini.google.com/app/s1',
+        addedAt: Date.now(),
+        sortIndex: 0,
+      },
+      {
+        conversationId: 'c_norm_1',
+        title: 'Norm 1',
+        starred: false,
+        url: 'https://gemini.google.com/app/n1',
+        addedAt: Date.now(),
+        sortIndex: 0,
+      },
+      {
+        conversationId: 'c_norm_2',
+        title: 'Norm 2',
+        starred: false,
+        url: 'https://gemini.google.com/app/n2',
+        addedAt: Date.now(),
+        sortIndex: 1,
+      },
+    ];
+
+    // In the rendered view list, c_star_1 is at 0, c_norm_1 is at 1, c_norm_2 is at 2.
+    // Insert new unstarred conversation c_new above c_norm_1 (rendered index 1).
+    typed.reorderOrMoveConversations(
+      ['c_new'],
+      '',
+      'folder-1',
+      1,
+      [
+        {
+          conversationId: 'c_new',
+          title: 'New Norm',
+          starred: false,
+          url: 'https://gemini.google.com/app/new',
+          addedAt: Date.now(),
+        },
+      ],
+    );
+
+    const folderConvs = typed.data.folderContents['folder-1'];
+    const unstarred = folderConvs.filter((c) => !c.starred);
+    // c_new should be placed BEFORE c_norm_1 in the unstarred group
+    expect(unstarred[0].conversationId).toBe('c_new');
+    expect(unstarred[1].conversationId).toBe('c_norm_1');
+    expect(unstarred[2].conversationId).toBe('c_norm_2');
+  });
+
+  it('clears all dragover highlights when clearAllDragOverHighlights is called or on drop/dragend', () => {
+    manager = new FolderManager();
+    const typed = manager as unknown as TestableFolderManager;
+
+    const container = document.createElement('div');
+    container.className = 'gv-folder-container';
+    typed.containerElement = container;
+
+    const el1 = document.createElement('div');
+    el1.className = 'gv-folder-list-dragover gv-folder-dragover';
+    const el2 = document.createElement('div');
+    el2.className = 'gv-reorder-above gv-reorder-gap-active';
+
+    container.appendChild(el1);
+    container.appendChild(el2);
+    document.body.appendChild(container);
+
+    expect(container.querySelectorAll('.gv-folder-dragover').length).toBe(1);
+    expect(container.querySelectorAll('.gv-reorder-gap-active').length).toBe(1);
+
+    typed.clearAllDragOverHighlights();
+
+    expect(container.querySelectorAll('.gv-folder-dragover').length).toBe(0);
+    expect(container.querySelectorAll('.gv-folder-list-dragover').length).toBe(0);
+    expect(container.querySelectorAll('.gv-reorder-above').length).toBe(0);
+    expect(container.querySelectorAll('.gv-reorder-gap-active').length).toBe(0);
+  });
+});
