+// parseStagedFilesFromPorcelain extracts staged relative file paths from `git status --porcelain -z` output.
+func parseStagedFilesFromPorcelain(output []byte) []string {
+	if len(output) == 0 {
+		return nil
+	}
+	var staged []string
+	entries := bytes.Split(output, []byte{0})
+	for i := 0; i < len(entries); i++ {
+		entry := entries[i]
+		if len(entry) < 4 {
+			continue
+		}
+		x := entry[0]
+		// Staged status X is not space (' '), untracked ('?'), or ignored ('!')
+		if x != ' ' && x != '?' && x != '!' {
+			filePath := string(entry[3:])
+			if filePath != "" {
+				staged = append(staged, filePath)
+			}
+			// In `git status --porcelain -z`, renames ('R') and copies ('C') have an extra NUL-terminated record for source path
+			if (x == 'R' || x == 'C') && i+1 < len(entries) {
+				i++
+			}
+		}
+	}
+	return staged
+}
+
+// parseChangedFilesFromPorcelain extracts all changed relative file paths from `git status --porcelain -z` output.
+func parseChangedFilesFromPorcelain(output []byte) []string {
+	if len(output) == 0 {
+		return nil
+	}
+	var changed []string
+	entries := bytes.Split(output, []byte{0})
+	for i := 0; i < len(entries); i++ {
+		entry := entries[i]
+		if len(entry) < 4 {
+			continue
+		}
+		x, y := entry[0], entry[1]
+		// Skip ignored files ('!')
+		if x == '!' || y == '!' {
+			continue
+		}
+		// File is changed if X or Y is not space (' ')
+		if x != ' ' || y != ' ' {
+			filePath := string(entry[3:])
+			if filePath != "" {
+				changed = append(changed, filePath)
+			}
+			// In `git status --porcelain -z`, renames ('R') and copies ('C') have an extra NUL-terminated record for source path
+			if (x == 'R' || x == 'C' || y == 'R' || y == 'C') && i+1 < len(entries) {
+				i++
+			}
+		}
+	}
+	return changed
+}
