+func TestParseStagedFilesFromPorcelain(t *testing.T) {
+	t.Parallel()
+
+	testCases := []struct {
+		name     string
+		input    []byte
+		expected []string
+	}{
+		{
+			name:     "empty output",
+			input:    []byte(""),
+			expected: nil,
+		},
+		{
+			name:     "staged modified file",
+			input:    []byte("M  src/main.go\x00"),
+			expected: []string{"src/main.go"},
+		},
+		{
+			name:     "staged added file",
+			input:    []byte("A  newfile.go\x00"),
+			expected: []string{"newfile.go"},
+		},
+		{
+			name:     "staged deleted file",
+			input:    []byte("D  oldfile.go\x00"),
+			expected: []string{"oldfile.go"},
+		},
+		{
+			name:     "staged rename",
+			input:    []byte("R  new.go\x00old.go\x00"),
+			expected: []string{"new.go"},
+		},
+		{
+			name:     "unstaged modified file (not staged)",
+			input:    []byte(" M src/main.go\x00"),
+			expected: nil,
+		},
+		{
+			name:     "untracked file (not staged)",
+			input:    []byte("?? untracked.go\x00"),
+			expected: nil,
+		},
+		{
+			name:     "ignored file (not staged)",
+			input:    []byte("!! ignored.go\x00"),
+			expected: nil,
+		},
+		{
+			name:     "mixed staged and unstaged files",
+			input:    []byte("M  staged.go\x00 M unstaged.go\x00A  added.go\x00?? untracked.go\x00"),
+			expected: []string{"staged.go", "added.go"},
+		},
+	}
+
+	for _, tc := range testCases {
+		t.Run(tc.name, func(t *testing.T) {
+			t.Parallel()
+			result := parseStagedFilesFromPorcelain(tc.input)
+			if len(result) != len(tc.expected) {
+				t.Fatalf("got %d staged files (%v), want %d (%v)", len(result), result, len(tc.expected), tc.expected)
+			}
+			for i := range result {
+				if result[i] != tc.expected[i] {
+					t.Errorf("result[%d] = %q, want %q", i, result[i], tc.expected[i])
+				}
+			}
+		})
+	}
+}
